using System.Threading.Tasks; using System.Web.Http; using EnterpriseInvoiceSystem.DTOs; using EnterpriseInvoiceSystem.Services;
namespace EnterpriseInvoiceSystem.Controllers { [RoutePrefix("api/customers")] public class CustomersController:ApiController { readonly CustomerService service=new CustomerService(); [HttpGet,Route("")] public async Task<IHttpActionResult> All(){return Ok(await service.GetAllAsync());} [HttpGet,Route("{id:int}")] public async Task<IHttpActionResult> Get(int id){var x=await service.GetAsync(id);return x==null?(IHttpActionResult)NotFound():Ok(x);} [HttpPost,Route("")] public async Task<IHttpActionResult> Post(CreateCustomerRequest r){if(!ModelState.IsValid)return BadRequest(ModelState);var x=await service.CreateAsync(r);return CreatedAtRoute("DefaultApi",new{id=x.Id},x);} [HttpPut,Route("{id:int}")] public async Task<IHttpActionResult> Put(int id,UpdateCustomerRequest r){if(!ModelState.IsValid)return BadRequest(ModelState);return await service.UpdateAsync(id,r)?StatusCode(System.Net.HttpStatusCode.NoContent):(IHttpActionResult)NotFound();} [HttpDelete,Route("{id:int}")] public async Task<IHttpActionResult> Delete(int id){var r=await service.DeleteAsync(id);return r==0?(IHttpActionResult)NotFound():r<0?Content(System.Net.HttpStatusCode.Conflict,new{message="Customer cannot be deleted because invoices reference it."}):StatusCode(System.Net.HttpStatusCode.NoContent);} } }
